def check_dangling_cnames(domain_list):
    dangling = []
    for domain in domain_list:
        try:
            answers = dns.resolver.resolve(domain, 'CNAME')
            for rdata in answers:
                cname_target = str(rdata.target)
                try:
                    dns.resolver.resolve(cname_target, 'A')
                except dns.resolver.NXDOMAIN:
                    # CNAME points to unclaimed resource
                    dangling.append((domain, cname_target))
        except:
